#!/usr/bin/env python3
"""Build a canonical fixture graph and a selected-world capability database."""

from __future__ import annotations

import argparse
from contextlib import closing
import json
from pathlib import Path
import sqlite3
from typing import Any
import uuid


PLUGIN_ROOT = Path(__file__).resolve().parents[1]
CANONICAL_SCHEMA = PLUGIN_ROOT / "schema" / "canonical.sql"
CAPABILITY_SCHEMA = PLUGIN_ROOT / "schema" / "capability.sql"

TABLE_COLUMNS = {
    "worlds": ("world_id", "name", "description", "enabled"),
    "nodes": (
        "node_id", "world_id", "type", "canonical_name", "summary", "state",
        "sensitivity", "valid_from", "valid_to", "last_seen_at", "superseded_by",
        "created_at", "updated_at",
    ),
    "node_aliases": ("alias", "node_id", "source", "confidence"),
    "edges": (
        "edge_id", "world_id", "from_node_id", "relation", "to_node_id", "state",
        "valid_from", "valid_to", "confidence", "evidence_count", "created_at",
        "updated_at",
    ),
    "evidence": (
        "evidence_id", "node_id", "edge_id", "source_kind", "source_ref",
        "occurred_at", "observed_at", "excerpt", "content_hash",
    ),
}


def _insert_rows(connection: sqlite3.Connection, table: str, rows: list[dict[str, Any]]) -> None:
    columns = TABLE_COLUMNS[table]
    placeholders = ", ".join("?" for _ in columns)
    connection.executemany(
        f"INSERT INTO {table} ({', '.join(columns)}) VALUES ({placeholders})",
        [tuple(row.get(column) for column in columns) for row in rows],
    )


def _fresh_database(path: Path, schema_path: Path) -> sqlite3.Connection:
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        path.unlink()
    connection = sqlite3.connect(path)
    connection.execute("PRAGMA foreign_keys = ON")
    connection.executescript(schema_path.read_text(encoding="utf-8"))
    return connection


def _build_canonical(path: Path, fixture: dict[str, Any]) -> None:
    with closing(_fresh_database(path, CANONICAL_SCHEMA)) as connection:
        with connection:
            for table in ("worlds", "nodes", "node_aliases", "edges", "evidence"):
                _insert_rows(connection, table, fixture.get(table, []))


def build_capability_connection(
    canonical_path: Path,
    selected_world: str,
    policy: dict[str, Any],
) -> sqlite3.Connection:
    canonical_uri = canonical_path.resolve().as_uri() + "?mode=ro"
    with closing(sqlite3.connect(canonical_uri, uri=True)) as canonical:
        canonical.row_factory = sqlite3.Row
        canonical_rows = {
            table: [dict(row) for row in canonical.execute(f"SELECT * FROM {table}")]
            for table in ("nodes", "node_aliases", "edges", "evidence")
        }

    included_states = set(policy.get("include_states", ["active"]))
    denied_sensitivity = set(policy.get("deny_sensitivity", []))
    allowed_types = set(policy.get("allow_node_types", []))
    included_sources = set(policy.get("include_sources", []))

    eligible_evidence = [
        row for row in canonical_rows["evidence"]
        if not included_sources or row["source_kind"] in included_sources
    ]
    evidenced_nodes = {row["node_id"] for row in eligible_evidence if row.get("node_id")}
    nodes = [
        row for row in canonical_rows["nodes"]
        if row["world_id"] == selected_world
        and row["state"] in included_states
        and row["sensitivity"] not in denied_sensitivity
        and (not allowed_types or row["type"] in allowed_types)
        and row["node_id"] in evidenced_nodes
    ]
    node_ids = {row["node_id"] for row in nodes}
    aliases = [
        row for row in canonical_rows["node_aliases"] if row["node_id"] in node_ids
    ]
    edges = [
        row for row in canonical_rows["edges"]
        if row["world_id"] == selected_world
        and row["state"] in included_states
        and row["from_node_id"] in node_ids
        and row["to_node_id"] in node_ids
    ]
    edge_ids = {row["edge_id"] for row in edges}
    evidence = [
        row for row in eligible_evidence
        if (row.get("node_id") in node_ids)
        or (row.get("edge_id") in edge_ids)
    ]

    connection = sqlite3.connect(":memory:")
    try:
        connection.execute("PRAGMA foreign_keys = ON")
        connection.executescript(CAPABILITY_SCHEMA.read_text(encoding="utf-8"))
        for table, rows in (
            ("nodes", nodes),
            ("node_aliases", aliases),
            ("edges", edges),
            ("evidence", evidence),
        ):
            _insert_rows(connection, table, rows)
        connection.commit()
        connection.execute("PRAGMA query_only = ON")
        return connection
    except Exception:
        connection.close()
        raise


def build_session(
    fixture_path: Path,
    policy_path: Path,
    selected_world: str,
    session_directory: Path,
    max_rows: int = 100,
    max_execution_ms: int = 1_000,
) -> Path:
    if max_rows <= 0 or max_execution_ms <= 0:
        raise ValueError("Query limits must be positive integers")
    fixture = json.loads(fixture_path.read_text(encoding="utf-8"))
    policies = json.loads(policy_path.read_text(encoding="utf-8")).get("worlds", {})
    if selected_world not in policies:
        raise ValueError(f"World {selected_world!r} is not configured by the policy")
    fixture_worlds = {world["world_id"] for world in fixture.get("worlds", [])}
    if selected_world not in fixture_worlds:
        raise ValueError(f"World {selected_world!r} is not present in the fixture")

    session_directory = session_directory.resolve()
    canonical_path = session_directory / "canonical.sqlite3"
    session_path = session_directory / "session.json"
    _build_canonical(canonical_path, fixture)

    session_identifier = uuid.uuid4().hex
    session = {
        "sessionIdentifier": session_identifier,
        "selectedWorld": selected_world,
        "policyContract": policies[selected_world],
        "canonicalDatabase": str(canonical_path),
        "queryAuditLog": str(
            session_directory / f"query-audit-{session_identifier}.jsonl"
        ),
        "queryLimits": {
            "maxRows": max_rows,
            "maxExecutionMs": max_execution_ms,
        },
        "schemaGuidance": {
            "nodes": list(TABLE_COLUMNS["nodes"]),
            "node_aliases": list(TABLE_COLUMNS["node_aliases"]),
            "edges": list(TABLE_COLUMNS["edges"]),
            "evidence": list(TABLE_COLUMNS["evidence"]),
        },
    }
    session_path.write_text(json.dumps(session, indent=2) + "\n", encoding="utf-8")
    return session_path


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--fixture", type=Path, required=True)
    parser.add_argument("--policy", type=Path, required=True)
    parser.add_argument("--world", required=True)
    parser.add_argument("--session-dir", type=Path, required=True)
    parser.add_argument("--max-rows", type=int, default=100)
    parser.add_argument("--max-execution-ms", type=int, default=1_000)
    arguments = parser.parse_args()
    session_path = build_session(
        arguments.fixture,
        arguments.policy,
        arguments.world,
        arguments.session_dir,
        arguments.max_rows,
        arguments.max_execution_ms,
    )
    session = json.loads(session_path.read_text(encoding="utf-8"))
    print(json.dumps({
        "selectedWorld": session["selectedWorld"],
        "sessionPath": str(session_path),
    }))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Minimal stdio MCP server exposing the policy-bounded SQL query tool."""

from __future__ import annotations

import json
import os
from pathlib import Path
import sqlite3
import sys
from typing import Any

from build_session import build_capability_connection
from query_harness import QueryAuditContext, QueryRejected, query


PROTOCOL_VERSION = "2025-06-18"


def _load_session() -> dict[str, Any]:
    session_path = os.environ.get("LOCAL_ONTOLOGY_SESSION")
    if not session_path:
        raise RuntimeError(
            "LOCAL_ONTOLOGY_SESSION must point to a session.json built by build_session.py"
        )
    return json.loads(Path(session_path).read_text(encoding="utf-8"))


def _startup_instructions(session: dict[str, Any]) -> str:
    world = session["selectedWorld"]
    policy = json.dumps(session["policyContract"], sort_keys=True)
    schema = json.dumps(session["schemaGuidance"], sort_keys=True)
    return (
        "GLOBAL MEMORY\n"
        "- This is a read-only, policy-bounded personal-memory database.\n"
        "- Query only when the request benefits from personal historical context.\n"
        "- Use nodes, edges, and evidence; recursive CTEs are available.\n"
        "- Treat SQL results as dated evidence and cite their provenance.\n"
        f"- The selected world is {world}; other worlds do not exist in this session.\n"
        f"- Policy contract: {policy}\n"
        f"- Schema guidance: {schema}\n"
        "- Do not attempt writes, PRAGMAs, ATTACH, extensions, or external access."
    )


def _tool_definition() -> dict[str, Any]:
    return {
        "name": "query_memory",
        "title": "Query Local Ontology",
        "description": (
            "Run one ordinary read-only SQL query against the selected world's "
            "capability database. Select evidence source_kind, source_ref, and "
            "occurred_at when retrieving facts so provenance is preserved."
        ),
        "inputSchema": {
            "type": "object",
            "properties": {
                "sql": {"type": "string", "description": "A SELECT or WITH query."}
            },
            "required": ["sql"],
            "additionalProperties": False,
        },
        "outputSchema": {
            "type": "object",
            "properties": {
                "rows": {"type": "array", "items": {"type": "object"}},
                "rowCount": {"type": "integer"},
                "truncated": {"type": "boolean"},
                "maxRows": {"type": "integer"},
            },
            "required": ["rows", "rowCount", "truncated", "maxRows"],
        },
        "annotations": {"readOnlyHint": True},
    }


def _success(identifier: Any, result: dict[str, Any]) -> dict[str, Any]:
    return {"jsonrpc": "2.0", "id": identifier, "result": result}


def _error(identifier: Any, code: int, message: str) -> dict[str, Any]:
    return {
        "jsonrpc": "2.0",
        "id": identifier,
        "error": {"code": code, "message": message},
    }


def handle(
    request: dict[str, Any],
    session: dict[str, Any],
    capability: sqlite3.Connection,
) -> dict[str, Any] | None:
    identifier = request.get("id")
    method = request.get("method")
    if method == "initialize":
        requested_version = request.get("params", {}).get("protocolVersion")
        return _success(identifier, {
            "protocolVersion": requested_version or PROTOCOL_VERSION,
            "capabilities": {"tools": {"listChanged": False}},
            "serverInfo": {"name": "local-ontology", "version": "0.1.0"},
            "instructions": _startup_instructions(session),
        })
    if method == "ping":
        return _success(identifier, {})
    if method == "tools/list":
        return _success(identifier, {"tools": [_tool_definition()]})
    if method == "tools/call":
        parameters = request.get("params", {})
        if parameters.get("name") != "query_memory":
            return _error(identifier, -32602, "Unknown tool")
        try:
            limits = session["queryLimits"]
            result = query(
                capability,
                parameters.get("arguments", {}).get("sql", ""),
                max_rows=limits["maxRows"],
                max_execution_ms=limits["maxExecutionMs"],
                audit_context=QueryAuditContext(
                    path=Path(session["queryAuditLog"]),
                    session_identifier=session["sessionIdentifier"],
                    world_identifier=session["selectedWorld"],
                ),
            )
        except QueryRejected as error:
            return _success(identifier, {
                "content": [{"type": "text", "text": str(error)}],
                "isError": True,
            })
        return _success(identifier, {
            "content": [{"type": "text", "text": json.dumps(result, ensure_ascii=False)}],
            "structuredContent": result,
            "isError": False,
        })
    if method and method.startswith("notifications/"):
        return None
    return _error(identifier, -32601, f"Method not found: {method}")


def main() -> None:
    try:
        session = _load_session()
    except (OSError, ValueError, RuntimeError) as error:
        print(str(error), file=sys.stderr)
        raise SystemExit(2) from error

    capability = build_capability_connection(
        Path(session["canonicalDatabase"]),
        session["selectedWorld"],
        session["policyContract"],
    )
    try:
        for line in sys.stdin:
            if not line.strip():
                continue
            try:
                request = json.loads(line)
                response = handle(request, session, capability)
            except (TypeError, ValueError) as error:
                response = _error(None, -32700, str(error))
            if response is not None:
                print(json.dumps(response, ensure_ascii=False), flush=True)
    finally:
        capability.close()


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Execute one ordinary read-only SQL query against a capability database."""

from __future__ import annotations

from dataclasses import dataclass
import hashlib
import json
from pathlib import Path
import re
import sqlite3
import time
from typing import Any


class QueryRejected(ValueError):
    """Raised when SQL is outside the read-only MVP query contract."""


@dataclass(frozen=True)
class QueryAuditContext:
    """Identity and destination for payload-free query audit entries."""

    path: Path
    session_identifier: str
    world_identifier: str

    def record(
        self,
        sql: object,
        execution_time_ms: float,
        row_count: int,
        outcome: str,
        truncated: bool,
    ) -> None:
        fingerprint_source = (
            " ".join(sql.split())
            if isinstance(sql, str)
            else f"<invalid:{type(sql).__name__}>"
        )
        entry = {
            "sqlFingerprint": hashlib.sha256(
                fingerprint_source.encode("utf-8")
            ).hexdigest(),
            "executionTimeMs": round(execution_time_ms, 3),
            "rowCount": row_count,
            "sessionIdentifier": self.session_identifier,
            "worldIdentifier": self.world_identifier,
            "outcome": outcome,
            "truncated": truncated,
        }
        try:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            with self.path.open("a", encoding="utf-8") as audit_file:
                audit_file.write(json.dumps(entry, sort_keys=True) + "\n")
        except OSError as error:
            raise QueryRejected("The query audit entry could not be recorded") from error


_READ_ONLY_ACTIONS = frozenset(
    {
        sqlite3.SQLITE_FUNCTION,
        sqlite3.SQLITE_READ,
        sqlite3.SQLITE_RECURSIVE,
        sqlite3.SQLITE_SELECT,
    }
)
_PROHIBITED_FUNCTIONS = frozenset(
    {"fts3_tokenizer", "load_extension", "readfile", "writefile"}
)
_LEADING_SQL = re.compile(
    r"(?:\s|--[^\r\n]*(?:\r?\n|$)|/\*.*?\*/)*([A-Za-z]+)",
    re.DOTALL,
)


def _is_prohibited_object(table: str | None, database: str | None) -> bool:
    normalized_table = (table or "").lower()
    normalized_database = (database or "").lower()
    return (
        normalized_database not in {"", "main"}
        or normalized_table.startswith("sqlite_")
        or normalized_table.startswith("pragma_")
    )


def _first_keyword(sql: str) -> str | None:
    match = _LEADING_SQL.match(sql)
    return match.group(1).lower() if match else None


def _execute_query(
    connection: sqlite3.Connection,
    sql: str,
    max_rows: int = 100,
    max_execution_ms: int = 1_000,
) -> dict[str, Any]:
    if not isinstance(sql, str):
        raise QueryRejected("SQL must be a string")
    if not isinstance(max_rows, int) or isinstance(max_rows, bool) or max_rows <= 0:
        raise QueryRejected("Row limit must be a positive integer")
    if (
        not isinstance(max_execution_ms, int)
        or isinstance(max_execution_ms, bool)
        or max_execution_ms <= 0
    ):
        raise QueryRejected("Execution time limit must be a positive integer")

    statement = sql.strip()
    if _first_keyword(statement) not in {"select", "with"}:
        raise QueryRejected("Only one SELECT or WITH statement is allowed")

    rejection_reason: str | None = None
    deadline = time.monotonic() + (max_execution_ms / 1_000)
    execution_timed_out = False

    def authorize(
        action: int,
        argument_one: str | None,
        argument_two: str | None,
        database: str | None,
        _trigger: str | None,
    ) -> int:
        nonlocal rejection_reason
        if action not in _READ_ONLY_ACTIONS:
            rejection_reason = "A prohibited SQL operation was rejected"
            return sqlite3.SQLITE_DENY
        if action == sqlite3.SQLITE_FUNCTION and (
            argument_two or argument_one or ""
        ).lower() in _PROHIBITED_FUNCTIONS:
            rejection_reason = "Use of a prohibited SQL function is not allowed"
            return sqlite3.SQLITE_DENY
        if action == sqlite3.SQLITE_READ and _is_prohibited_object(
            argument_one, database
        ):
            rejection_reason = "Access to a prohibited database object is not allowed"
            return sqlite3.SQLITE_DENY
        return sqlite3.SQLITE_OK

    def enforce_deadline() -> int:
        nonlocal execution_timed_out
        execution_timed_out = time.monotonic() >= deadline
        return 1 if execution_timed_out else 0

    previous_row_factory = connection.row_factory
    connection.row_factory = sqlite3.Row
    connection.set_authorizer(authorize)
    connection.set_progress_handler(enforce_deadline, 100)
    try:
        cursor = connection.execute(statement)
        fetched = cursor.fetchmany(max_rows + 1)
        truncated = len(fetched) > max_rows
        rows = [dict(row) for row in fetched[:max_rows]]
        return {
            "rows": rows,
            "rowCount": len(rows),
            "truncated": truncated,
            "maxRows": max_rows,
        }
    except sqlite3.Error as error:
        if execution_timed_out:
            rejection_reason = (
                f"Query exceeded the {max_execution_ms} ms execution time limit"
            )
        raise QueryRejected(rejection_reason or str(error)) from error
    finally:
        connection.set_progress_handler(None, 0)
        connection.set_authorizer(None)
        connection.row_factory = previous_row_factory


def query(
    connection: sqlite3.Connection,
    sql: str,
    max_rows: int = 100,
    max_execution_ms: int = 1_000,
    *,
    audit_context: QueryAuditContext | None = None,
) -> dict[str, Any]:
    """Run one bounded read-only statement and record the attempt when configured."""

    started = time.monotonic()
    row_count = 0
    truncated = False
    outcome = "failed"
    try:
        result = _execute_query(connection, sql, max_rows, max_execution_ms)
        row_count = result["rowCount"]
        truncated = result["truncated"]
        outcome = "succeeded"
        return result
    except QueryRejected:
        outcome = "rejected"
        raise
    finally:
        if audit_context is not None:
            audit_context.record(
                sql=sql,
                execution_time_ms=(time.monotonic() - started) * 1_000,
                row_count=row_count,
                outcome=outcome,
                truncated=truncated,
            )

